case 'condition_access': {
  // Visual security gate: Users table + ACCESS_CODE → Authorized / Denied
  const mode = String(node.data.mode || 'code').toLowerCase();
  const user = AccessUsers.findByPhone(ctx.phone);
  if (!user || !user.is_active) {
    console.log(`[Workflow] condition_access DENIED unauthorized ${ctx.phone}`);
    return { output: 'output_2' };
  }
  if (mode === 'whitelist' || mode === 'whitelist_only') {
    console.log(`[Workflow] condition_access AUTHORIZED whitelist ${ctx.phone}`);
    return { output: 'output_1' };
  }
  if (mode === 'unlocked' || mode === 'active') {
    const ok = AccessUsers.isUnlocked(ctx.phone);
    console.log(
      `[Workflow] condition_access ${ok ? 'AUTHORIZED' : 'DENIED'} unlocked-check ${ctx.phone}`
    );
    return { output: ok ? 'output_1' : 'output_2' };
  }
  // mode=code (default): exact ACCESS_CODE unlocks; already-active chatter stays Denied (silent)
  if (AccessUsers.isUnlocked(ctx.phone)) {
    const incoming = AccessUsers.normalizeCode(ctx.message || ctx.body || '');
    const assigned = AccessUsers.normalizeCode(user.access_code);
    const resend = incoming && assigned && incoming === assigned;
    console.log(
      `[Workflow] condition_access ${resend ? 'AUTHORIZED' : 'DENIED'} already-active ${ctx.phone}`
    );
    return { output: resend ? 'output_1' : 'output_2' };
  }
  const unlock = AccessUsers.tryUnlock(ctx.phone, ctx.message || ctx.body || '');
  console.log(
    `[Workflow] condition_access ${unlock.ok ? 'AUTHORIZED' : 'DENIED'} code-check ${ctx.phone} reason=${unlock.reason}`
  );
  return { output: unlock.ok ? 'output_1' : 'output_2' };
}

